// === Tab: mySketch ===
particles=[]

setup=()=>{
  createCanvas(1112, 834)
  colorMode(HSB,360)
	background(0)
  noStroke()
  for(i=0;i<1000;i++){
    particles[i]={
      pos:createVector(random(width),random(height)),
      vel:createVector(),
      nbhd:0
    }
  }
}

draw=()=> {
  background(0,10)
  t=frameCount/100
  mx=noise(t,0)*width
  my=noise(t,1)*height


for(p of particles){
  p.nbhd=0
  dis=sqrt((mx-p.pos.x)**2+(my-p.pos.y)**2)
  if(dis>200&&dis<300){
    angle=atan2(my-p.pos.y,mx-p.pos.x)+PI/2
    p.vel.add(p5.Vector.fromAngle(angle,1))
  }
}

  for(i=particles.length;i--;){
    a=particles[i]
    for(j=i;j--;){
      b=particles[j]
      dis=sqrt((a.pos.x-b.pos.x)**2+(a.pos.y-b.pos.y)**2)
      if(dis<81){
        a.nbhd++
        b.nbhd++
      }

      if(dis<16){        
        angle=atan2(a.pos.y-b.pos.y,a.pos.x-b.pos.x)
        a.vel.add(p5.Vector.fromAngle(angle,1))
        b.vel.add(p5.Vector.fromAngle(angle,-1))
      }
    }
  }

  for(p of particles){
    p.vel.mult(.9)
    p.pos.add(p.vel)
    p.pos.x=(p.pos.x+width)%width
    p.pos.y=(p.pos.y+height)%height
    fill(p.nbhd*10%360,360,360)
    ellipse(p.pos.x,p.pos.y,8,8)
  }
}

// save jpg
let lapse = 0;    // mouse timer
function mousePressed(){
  if (millis() - lapse > 400){
    save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
    lapse = millis();
  } 
}

